//! Local pet storage: `<app data>/pets/<id>/{manifest.json, sprite.png}`.
//! Original photos are never written here — only the processed sprite.

use std::{fs, path::PathBuf};

use tauri::{ipc::Request, ipc::Response, AppHandle, Manager};

use crate::settings;

pub const SPRITE_FILE: &str = "sprite.png";
const MANIFEST_FILE: &str = "manifest.json";
const MAX_SPRITE_BYTES: usize = 8 * 1024 * 1024;

/// Ids are generated by the app (UUIDs); anything else is rejected to rule out path traversal.
pub fn valid_id(id: &str) -> bool {
    !id.is_empty()
        && id.len() <= 64
        && id
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
}

fn pets_root(app: &AppHandle) -> Result<PathBuf, String> {
    Ok(app
        .path()
        .app_data_dir()
        .map_err(|e| e.to_string())?
        .join("pets"))
}

fn pet_dir(app: &AppHandle, id: &str) -> Result<PathBuf, String> {
    if !valid_id(id) {
        return Err(format!("invalid pet id: {id}"));
    }
    Ok(pets_root(app)?.join(id))
}

pub fn exists(app: &AppHandle, id: &str) -> bool {
    pet_dir(app, id)
        .map(|d| d.join(MANIFEST_FILE).is_file() && d.join(SPRITE_FILE).is_file())
        .unwrap_or(false)
}

fn read_manifests(root: &std::path::Path) -> Vec<serde_json::Value> {
    let Ok(entries) = fs::read_dir(root) else {
        return Vec::new();
    };
    let mut pets: Vec<serde_json::Value> = entries
        .flatten()
        .filter_map(|e| fs::read_to_string(e.path().join(MANIFEST_FILE)).ok())
        .filter_map(|s| serde_json::from_str(&s).ok())
        .collect();
    pets.sort_by(|a, b| {
        a["createdAt"]
            .as_str()
            .unwrap_or("")
            .cmp(b["createdAt"].as_str().unwrap_or(""))
    });
    pets
}

#[tauri::command]
pub fn list_pets(app: AppHandle) -> Result<Vec<serde_json::Value>, String> {
    Ok(read_manifests(&pets_root(&app)?))
}

#[tauri::command]
pub fn get_pet(app: AppHandle, id: String) -> Result<serde_json::Value, String> {
    let s =
        fs::read_to_string(pet_dir(&app, &id)?.join(MANIFEST_FILE)).map_err(|e| e.to_string())?;
    serde_json::from_str(&s).map_err(|e| e.to_string())
}

/// Returns the sprite PNG as raw bytes (no JSON encoding).
#[tauri::command]
pub fn get_pet_sprite(app: AppHandle, id: String) -> Result<Response, String> {
    let bytes = fs::read(pet_dir(&app, &id)?.join(SPRITE_FILE)).map_err(|e| e.to_string())?;
    Ok(Response::new(bytes))
}

/// Raw-body command: the sprite PNG is the request body, the pet id is the `pet-id` header.
#[tauri::command]
pub fn save_pet_sprite(app: AppHandle, request: Request<'_>) -> Result<(), String> {
    let tauri::ipc::InvokeBody::Raw(bytes) = request.body() else {
        return Err("expected raw PNG body".into());
    };
    if bytes.len() > MAX_SPRITE_BYTES || !bytes.starts_with(b"\x89PNG\r\n\x1a\n") {
        return Err("sprite must be a PNG under 8 MB".into());
    }
    let id = request
        .headers()
        .get("pet-id")
        .and_then(|v| v.to_str().ok())
        .ok_or("missing pet-id header")?;
    let dir = pet_dir(&app, id)?;
    fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
    settings::write_atomic(&dir.join(SPRITE_FILE), bytes)
}

/// Writes the manifest (after the sprite) and puts the new pet out on the desktop.
#[tauri::command]
pub fn save_pet_manifest(app: AppHandle, manifest: serde_json::Value) -> Result<(), String> {
    let id = manifest["id"]
        .as_str()
        .ok_or("manifest.id missing")?
        .to_string();
    let dir = pet_dir(&app, &id)?;
    if !dir.join(SPRITE_FILE).is_file() {
        return Err("save the sprite before the manifest".into());
    }
    let bytes = serde_json::to_vec_pretty(&manifest).map_err(|e| e.to_string())?;
    settings::write_atomic(&dir.join(MANIFEST_FILE), &bytes)?;
    settings::apply(&app, |s| {
        if !s.active_pets.contains(&id) {
            s.active_pets.push(id.clone());
        }
        s.pets_visible = true;
    })?;
    Ok(())
}

/// Deletes the pet's sprite and manifest. (Phase 3 also deletes its cloud copy.)
#[tauri::command]
pub fn delete_pet(app: AppHandle, id: String) -> Result<(), String> {
    let dir = pet_dir(&app, &id)?;
    settings::apply(&app, |s| s.active_pets.retain(|p| p != &id))?;
    if dir.exists() {
        fs::remove_dir_all(&dir).map_err(|e| e.to_string())?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rejects_path_traversal_ids() {
        assert!(valid_id("3f2a9c1e-7b5d-4e8f-9a0b-1c2d3e4f5a6b"));
        for bad in [
            "",
            "../etc",
            "a/b",
            "A",
            "x".repeat(65).as_str(),
            "a\\b",
            "a.b",
        ] {
            assert!(!valid_id(bad), "{bad:?} should be invalid");
        }
    }

    #[test]
    fn manifests_are_sorted_by_creation_and_bad_dirs_skipped() {
        let root = tempfile::tempdir().unwrap();
        for (id, at) in [("b", "2026-02-01"), ("a", "2026-01-01")] {
            let d = root.path().join(id);
            fs::create_dir_all(&d).unwrap();
            fs::write(
                d.join(MANIFEST_FILE),
                format!(r#"{{"id":"{id}","createdAt":"{at}"}}"#),
            )
            .unwrap();
        }
        fs::create_dir_all(root.path().join("junk")).unwrap();
        let ids: Vec<_> = read_manifests(root.path())
            .iter()
            .map(|m| m["id"].as_str().unwrap().to_string())
            .collect();
        assert_eq!(ids, ["a", "b"]);
    }
}
